PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_versions VALUES(1,datetime('now'));
CREATE TABLE IF NOT EXISTS workspace(id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,mime TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reference_records(id TEXT PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL DEFAULT '',deleted INTEGER NOT NULL DEFAULT 0,favorite INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL CHECK(json_valid(payload)),updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reference_category ON reference_records(deleted,category,favorite);
CREATE TABLE IF NOT EXISTS reference_blocks(reference_id TEXT NOT NULL REFERENCES reference_records(id) ON DELETE CASCADE,id TEXT NOT NULL,position INTEGER NOT NULL,kind TEXT NOT NULL,file_id TEXT REFERENCES files(id),payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(reference_id,id));
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY,name TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),deleted INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equipment(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,owner_id TEXT REFERENCES members(id),ownership TEXT NOT NULL CHECK(ownership IN ('team','personal')),payload TEXT NOT NULL CHECK(json_valid(payload)),deleted INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rental_shops(id TEXT PRIMARY KEY,name TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),deleted INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS locations(id TEXT PRIMARY KEY,name TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),deleted INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS productions(id TEXT PRIMARY KEY,name TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),deleted INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,production_id TEXT REFERENCES productions(id),parent_id TEXT REFERENCES projects(id),payload TEXT NOT NULL CHECK(json_valid(payload)),deleted INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS project_production ON projects(production_id,deleted);
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY,production_id TEXT REFERENCES productions(id),name TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS team_members(team_id TEXT REFERENCES teams(id),member_id TEXT REFERENCES members(id),role TEXT NOT NULL CHECK(role IN ('leader','member')),PRIMARY KEY(team_id,member_id));
CREATE TABLE IF NOT EXISTS project_members(project_id TEXT REFERENCES projects(id),member_id TEXT REFERENCES members(id),role TEXT NOT NULL CHECK(role IN ('leader','member')),PRIMARY KEY(project_id,member_id));
CREATE TABLE IF NOT EXISTS programs(id TEXT PRIMARY KEY,production_id TEXT NOT NULL REFERENCES productions(id),location_id TEXT REFERENCES locations(id),starts_at TEXT,ends_at TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY,program_id TEXT NOT NULL REFERENCES programs(id),member_id TEXT REFERENCES members(id),equipment_id TEXT REFERENCES equipment(id),role TEXT NOT NULL,position TEXT,starts_at TEXT,ends_at TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX IF NOT EXISTS assignment_member_time ON assignments(member_id,starts_at,ends_at);
CREATE INDEX IF NOT EXISTS assignment_equipment_time ON assignments(equipment_id,starts_at,ends_at);
CREATE TABLE IF NOT EXISTS project_equipment(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),equipment_id TEXT NOT NULL REFERENCES equipment(id),status TEXT NOT NULL DEFAULT 'planned',payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS rentals(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),shop_id TEXT REFERENCES rental_shops(id),name TEXT NOT NULL,starts_at TEXT,due_at TEXT,returned_at TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX IF NOT EXISTS unreturned_rentals ON rentals(project_id,returned_at,due_at);
CREATE TABLE IF NOT EXISTS equipment_checks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),equipment_id TEXT REFERENCES equipment(id),rental_id TEXT REFERENCES rentals(id),checked_by TEXT REFERENCES members(id),checked_at TEXT NOT NULL,status TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS tasks(scope_type TEXT NOT NULL,scope_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT,owner TEXT,due TEXT,done INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(scope_type,scope_id,id));
CREATE INDEX IF NOT EXISTS task_owner_due ON tasks(owner,done,due);
CREATE TABLE IF NOT EXISTS schedules(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,location_id TEXT REFERENCES locations(id),payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(project_id,id));
CREATE TABLE IF NOT EXISTS modules(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,position INTEGER NOT NULL,type TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(project_id,id));
CREATE TABLE IF NOT EXISTS assets(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(project_id,id));
CREATE TABLE IF NOT EXISTS feedback(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(project_id,id));
CREATE TABLE IF NOT EXISTS reference_project_links(reference_id TEXT REFERENCES reference_records(id),project_id TEXT REFERENCES projects(id),module_id TEXT,PRIMARY KEY(reference_id,project_id,module_id));
CREATE TABLE IF NOT EXISTS permission_grants(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,collection TEXT NOT NULL,record_id TEXT,permission TEXT CHECK(permission IN ('read','edit','manage')),starts_at TEXT,ends_at TEXT,revoked_at TEXT);
CREATE INDEX IF NOT EXISTS grant_account ON permission_grants(account_id,collection,record_id,ends_at);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,collection TEXT NOT NULL,record_id TEXT,created_at TEXT NOT NULL,payload TEXT);
CREATE TABLE IF NOT EXISTS app_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,member_id TEXT NOT NULL UNIQUE,role TEXT NOT NULL CHECK(role IN ('superadmin','admin','operator','advanced','viewer')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_bootstrap(id INTEGER PRIMARY KEY CHECK(id=1),user_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_invites(token_hash TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,member_id TEXT NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER,created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tab_permissions(owner_id TEXT NOT NULL,tab_id TEXT NOT NULL,policy TEXT NOT NULL,updated_by TEXT NOT NULL,PRIMARY KEY(owner_id,tab_id));
CREATE TABLE IF NOT EXISTS file_uploaders(file_id TEXT PRIMARY KEY,user_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS access_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts(key TEXT PRIMARY KEY,window_start INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS local_credentials(user_id TEXT PRIMARY KEY REFERENCES app_users(id),password_hash TEXT NOT NULL,mfa_secret TEXT,pending_mfa TEXT,last_totp INTEGER NOT NULL DEFAULT -1);
CREATE TABLE IF NOT EXISTS local_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES app_users(id),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,aal INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS local_pending(email TEXT NOT NULL,purpose TEXT NOT NULL,code_hash TEXT NOT NULL,payload TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL,PRIMARY KEY(email,purpose));
CREATE TABLE IF NOT EXISTS local_recovery_codes(user_id TEXT NOT NULL REFERENCES app_users(id),code_hash TEXT NOT NULL,used INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,code_hash));

CREATE TABLE IF NOT EXISTS local_session_preferences(token_hash TEXT PRIMARY KEY REFERENCES local_sessions(token_hash) ON DELETE CASCADE,remembered INTEGER NOT NULL DEFAULT 0 CHECK(remembered IN (0,1)));
